"""Pattern import end to end on SYNTHETIC fixtures (tests/fixtures/patterns). Real-pattern validation is a separate manual protocol.
Usage: FF_KEY=flossfox-dev.v1 python3 tests/pattern_import_e2e.py URL"""
import sys, os, json
from playwright.sync_api import sync_playwright
B = sys.argv[1]; KEY = os.environ.get('FF_KEY', 'flossfox-dev.v1'); PFX = KEY.replace('.v1', '')
FX = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'fixtures', 'patterns')
SHOTS = os.environ.get('SHOTS', '/workspace/ci005-shots/major')
R = []
def ok(n, c, d=''):
    R.append(c); print(('PASS ' if c else 'FAIL ') + n + ('' if c else f'  -> {str(d)[:300]}'))
SEED = "localStorage.setItem('%s.tour.v1','{\"status\":\"dismissed\"}');localStorage.setItem('%s.hints.v1','off')" % (PFX, PFX)
with sync_playwright() as p:
    b = p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    def page(init=''):
        c = b.new_context(viewport={'width': 390, 'height': 844}, is_mobile=True, device_scale_factor=2); c.add_init_script(SEED + ';' + init)
        g = c.new_page(); g.errs = []; g.on('pageerror', lambda e: g.errs.append(str(e))); g.on('dialog', lambda d: d.accept()); g.goto(B); g.wait_for_timeout(300); return g
    def load(g, name, wait=2500):
        g.click('.pat-launch'); g.set_input_files('#patFile', os.path.join(FX, name)); g.wait_for_function("!/Reading selected file/.test(document.getElementById('patInfo').textContent)", timeout=30000); g.wait_for_timeout(200)
        return g.inner_text('#patInfo') + ' ' + (g.inner_text('#patUnreadable') if g.locator('#patUnreadable').count() else ''), g.evaluate("[...document.querySelectorAll('#patRows .pat-row b')].map(b=>b.textContent)")
    def projects(g): return g.evaluate(f"(JSON.parse(localStorage.getItem('{KEY}'))||{{projects:[]}}).projects")
    # 1 text PDF + save + land on project strip
    g = page()
    info, codes = load(g, 'native-legend.pdf')
    ok('I1 text PDF: colors found locally, nothing sent online', codes == ['DMC 310', 'DMC 321', 'DMC 666', 'DMC 3865'] and 'Nothing was sent online' in info, (codes, info))
    ok('I1b AI page picker and AI button hidden while AI is off', g.locator('#patPageBox').is_hidden() and g.locator('text=Preview page for AI').count() in (0,) or g.locator('text=Preview page for AI').is_hidden())
    ok('I1c Create stays disabled until the one confirmation, and says why next to the button', g.locator('#patImport').is_disabled() and 'Tick the box above to create your project.' in g.inner_text('#patWhy') and g.locator('#patWhy a[href="#patAll"]').count() == 1, g.inner_text('#patWhy'))
    ok('I1c2 no per-color checkboxes (only the one confirmation)', g.locator('#patRows .pat-row input[type=checkbox]').count() == 0 and g.locator('#patAll').count() == 1)
    for t in g.locator('#patRows input[type=checkbox]').all(): t.check()
    g.fill('#patName', 'Synthetic sampler'); g.click('#patImport'); g.wait_for_timeout(400)
    pr = projects(g)
    ok('I1d save: one project with stated amounts only', len(pr) == 1 and {i['code']: i['qty'] for i in pr[0]['items']} == {'310': 2, '321': 1, '666': None, '3865': None}, pr)
    ok('I1e lands on the project with the step strip; next step focused', g.locator('#projEdit').is_visible() and g.locator('#pFlow [aria-current=step]').count() == 1 and 'Pattern saved with 4 colors' in g.inner_text('#projStatus'), g.inner_text('#projStatus'))
    g.screenshot(path=os.path.join(SHOTS, '11-import-landed.png'))
    # 2 inventory comparison after import
    h = page("localStorage.setItem('%s.threads.v1',JSON.stringify({schema:2,threads:{'310':{n:3,partial:false,restock:false,updated:'2026-10-01T00:00:00Z'},'321':{n:0,partial:true,restock:false,updated:'2026-10-01T00:00:00Z'}}}))" % PFX)
    load(h, 'native-legend.pdf')
    for t in h.locator('#patRows input[type=checkbox]').all(): t.check()
    h.click('#patImport'); h.wait_for_timeout(400)
    ok('I2 after import Pip checks the collection automatically (banner shown)', 'Pip checked your threads' in h.inner_text('#pAuto'), h.inner_text('#pAuto'))
    h.click('#pFlow [data-flow=cmp]'); h.wait_for_timeout(200)
    cmp = h.inner_text('#pCmp')
    ok('I2b comparison uses the existing engine: 310 owned, others short/missing', 'Compared with my thread collection' in cmp and '1 owned' in cmp.replace('\n', ' ').replace('✓ ', ''), cmp[:300])
    if h.locator('#pUseColl').count():
        h.click('#pUseColl'); h.wait_for_timeout(200)
        if h.locator('#pApplyColl').count(): h.click('#pApplyColl'); h.wait_for_timeout(200)
    h.screenshot(path=os.path.join(SHOTS, '12-import-compared.png'), full_page=False)
    ok('I2c imported items flow into the shopping list without re-entry', h.locator('#pPlan').count() == 1)
    # 3 column table
    k = page(); info, codes = load(k, 'column-table-legend.pdf')
    ok('I3 column-table legend: codes taken, Blanc as White', codes == ['DMC 310', 'DMC WHITE', 'DMC 3865', 'DMC 321'], codes)
    vals = k.evaluate("[...document.querySelectorAll('#patRows input[type=number]')].map(i=>i.value)")
    ok('I3b unlabeled numbers are not filled in', all(v == '' for v in vals), vals)
    ok('I3c plain-language warning shown', 'no label' in k.inner_text('#patRows'))
    k.screenshot(path=os.path.join(SHOTS, '13-column-table.png'), full_page=True)
    k.click('#ffPatternDialog .pat-header button'); k.wait_for_timeout(200)
    ok('I3d cancel (Close) saves nothing', projects(k) == [] and not k.locator('#ffPatternDialog').count())
    # 4 specialty + misrecognition + ambiguous
    s = page(); info, codes = load(s, 'specialty-legend.pdf')
    ok('I4 specialty: only stranded cotton rows', codes == ['DMC 310', 'DMC 115'], codes)
    ok('I4b specialty lines shown as not imported', s.locator('#patSkipped').count() == 1 and '5 lines not imported' in s.inner_text('#patSkipped summary'), s.inner_text('#patRows')[:300])
    s.click('#patSkipped summary'); s.screenshot(path=os.path.join(SHOTS, '14-specialty.png'), full_page=True); s.click('#ffPatternDialog .pat-header button')
    info, codes = load(s, 'misrecognition-legend.pdf')
    ok('I5 misread codes not imported; listed for checking', codes == ['DMC 321', 'DMC 415', 'DMC 01'] and 'not recognized' in s.text_content('#patSkipped'), (codes, s.inner_text('#patRows')[:200]))
    s.click('#ffPatternDialog .pat-header button')
    info, codes = load(s, 'ambiguous-qty-legend.pdf')
    vals = s.evaluate("[...document.querySelectorAll('#patRows input[type=number]')].map(i=>i.value)")
    ok('I6 ambiguous amounts: none guessed (666 -, 321 range -, 413 approx 1, 3865 1)', vals[0::2] == ['', '', '1', '1'], vals)
    s.click('#ffPatternDialog .pat-header button')
    info, codes = load(s, 'repeated-codes-2pages.pdf')
    ok('I7 repeated code on two pages: one row, amounts cleared', codes.count('DMC 310') == 1 and s.evaluate("document.querySelector('#patRows input[type=number]').value") == '', codes)
    s.click('#ffPatternDialog .pat-header button')
    info, codes = load(s, 'row-numbers-dimensions.pdf')
    vals = s.evaluate("[...document.querySelectorAll('#patRows input[type=number]')].map(i=>i.value)")
    ok('I7b row numbers vs codes vs dimensions: 310, 321, 3865 only; only the labeled amount filled', codes == ['DMC 310', 'DMC 321', 'DMC 3865'] and vals[0::2] == ['', '', '1'] and 'row number or symbol' in s.inner_text('#patRows'), (codes, vals))
    s.click('#ffPatternDialog .pat-header button')
    # 5 scanned / image / bad files
    info, codes = load(s, 'scanned-image-only.pdf')
    ok('I8 scanned PDF: no text, no colors invented, manual paste offered', codes == [] and "couldn't find any colors" in s.inner_text('#patUnreadable'), (info, codes))
    s.click('#ffPatternDialog .pat-header button')
    info, codes = load(s, 'legend-scan.png')
    ok('I9 legend image (PDF only): friendly "only PDFs" message, nothing read, paste box opened', codes == [] and 'Only PDFs work right now' in info and 'Import stopped' not in info and s.evaluate("document.querySelector('#ffPatternDialog details.pat-manual').open") and projects(s) == [], info)
    ok('I9b file input accepts PDFs only', s.get_attribute('#patFile', 'accept') == '.pdf,application/pdf', s.get_attribute('#patFile', 'accept'))
    s.click('#ffPatternDialog .pat-header button')
    for bad in ['password-protected.pdf', 'fake.pdf']:
        info, codes = load(s, bad)
        ok(f'I10 {bad}: refused with a message, nothing imported', codes == [] and projects(s) == [], info); s.click('#ffPatternDialog .pat-header button')
    info, codes = load(s, 'large-35pages.pdf', 6000)
    ok('I11 35-page PDF processed locally without hanging', 'Processed' in info or 'pages' in info, info); s.click('#ffPatternDialog .pat-header button')
    # 6 manual paste path
    s.click('.pat-launch'); s.click('#ffPatternDialog details.pat-manual summary'); s.fill('#patPaste', 'X 310 Black 2400 2\nDMC 321 Red 2 skeins'); s.click('#ffPatternDialog button:text-is("Find colors")'); s.wait_for_timeout(200)
    ok('I12 manual legend paste uses the same rules', s.evaluate("[...document.querySelectorAll('#patRows .pat-row b')].map(b=>b.textContent)") == ['DMC 310', 'DMC 321'])
    # 7 Barbara A: full DMC color chart PDFs and image-only PDFs add nothing and say so plainly
    BB = os.environ.get('BARBARA_SHOTS', '')
    z = page()
    for fx in ('dmc-color-chart.pdf', 'dmc-color-chart-3col.pdf'):
        info, codes = load(z, fx, 4000)
        ok(f'A1 {fx}: whole-catalog PDF adds no colors and says why', codes == [] and "couldn't find any colors" in info and 'DMC color chart' in info and z.locator('#patImport').is_disabled(), (len(codes), info))
        if BB and fx == 'dmc-color-chart.pdf': z.screenshot(path=os.path.join(BB, 'A-unreadable-color-chart-pdf-390.png'))
        z.click('#ffPatternDialog .pat-header button')
    info, codes = load(z, 'scanned-image-only.pdf')
    ok('A2 image-only PDF: plain "couldn\'t read" message, paste box opened, nothing added', codes == [] and "couldn't find any colors" in info and z.evaluate("document.querySelector('#ffPatternDialog details.pat-manual').open") and projects(z) == [], info)
    if BB: z.screenshot(path=os.path.join(BB, 'A-unreadable-image-only-pdf-390.png'))
    z.click('#ffPatternDialog .pat-header button')
    info, codes = load(z, 'pattern-with-dmc-chart.pdf', 4000)
    ok('A3 pattern + appended DMC chart: only the 4 key colors, chart pages named as skipped', codes == ['DMC 310', 'DMC 321', 'DMC 3865', 'DMC 815'] and 'look like a full DMC color chart' in info, (codes, info))
    # 8 Barbara B: one confirmation, Unknown amounts carried as needs attention, saved + survives reload (390 touch)
    if BB: z.locator('#patWhy').scroll_into_view_if_needed(); z.screenshot(path=os.path.join(BB, 'B-disabled-button-explanation-390.png'))
    z.check('#patAll')
    ok('B1 after the one confirmation Create is enabled and the note says unknown amounts become Needs attention', not z.locator('#patImport').is_disabled() and 'Needs attention' in z.inner_text('#patWhy'), z.inner_text('#patWhy'))
    z.fill('#patName', 'Vampire duo test'); z.click('#patImport'); z.wait_for_timeout(500)
    pz = [x for x in projects(z) if x['name'] == 'Vampire duo test']
    ok('B2 project saved with all 4 colors, unknown amounts kept as Unknown (null)', len(pz) == 1 and sorted(i['code'] for i in pz[0]['items']) == ['310', '321', '3865', '815'] and all(i['qty'] is None for i in pz[0]['items']), pz)
    ok('C1 visible confirmation says where it went, with a button to see all projects', z.locator('#patSavedBox').is_visible() and 'is in My Projects with 4 colors' in z.inner_text('#patSavedBox') and z.locator('#patSavedBox button:text-is("See all my projects")').count() == 1, z.inner_text('#patSavedBox') if z.locator('#patSavedBox').count() else None)
    if BB: z.screenshot(path=os.path.join(BB, 'C-post-create-confirmation-390.png'))
    ok('B3 project shows 4 colors needing attention', '4 need attention' in z.evaluate("document.getElementById('projList').innerText") or 'Needs attention' in z.inner_text('#projectsView'), z.inner_text('#projectsView')[:300])
    z.reload(); z.wait_for_timeout(400); z.click('#tabProjects'); z.wait_for_timeout(300)
    if z.locator('#pClose').is_visible(): z.click('#pClose')
    ok('B4 after reload the project is listed in My Projects', 'Vampire duo test' in z.inner_text('#projList'), z.inner_text('#projList')[:200])
    ok('C2 import entry point also on My Projects', z.locator('#patLaunchProjects').is_visible())
    z.click('#patLaunchProjects'); ok('C2b it opens the importer', z.locator('#ffPatternDialog').is_visible()); z.click('#ffPatternDialog .pat-header button')
    # B5 touch: tap path on a phone context
    tc = b.new_context(viewport={'width': 390, 'height': 844}, is_mobile=True, has_touch=True, device_scale_factor=2); tc.add_init_script(SEED); t = tc.new_page(); t.errs = []; t.on('pageerror', lambda e: t.errs.append(str(e))); t.goto(B); t.wait_for_timeout(300)
    t.tap('.pat-launch'); t.set_input_files('#patFile', os.path.join(FX, 'column-table-legend.pdf')); t.wait_for_timeout(2500); t.tap('#patAll'); t.locator('#patImport').scroll_into_view_if_needed(); t.tap('#patImport'); t.wait_for_timeout(500)
    ok('B5 touch taps: confirm + Create saves the project', any(x['name'] == 'column-table-legend' for x in projects(t)), [x['name'] for x in projects(t)])
    # 9 Pixel strings: exact plural forms (N=1, N>1), unreadable sentences, help, screenshots
    def paste(g, txt):
        g.click('.pat-launch'); g.click('#ffPatternDialog details.pat-manual summary'); g.fill('#patPaste', txt); g.click('#ffPatternDialog button:text-is("Find colors")'); g.wait_for_timeout(200)
    def chk(cond, name, d=''): ok(name, cond, d)
    for n, txt in ((1, 'DMC 310 Black 2 skeins\nDMC 321 Red'), (3, 'DMC 310 Black 2 skeins\nDMC 321 Red\nDMC 666 Red\nDMC 815 Garnet')):
        p = page(); paste(p, txt); w = p.inner_text('#patWhy')
        one = '1 color has no clear amount yet, so it\'ll go under Needs attention for you to fill in later.'
        many = f'{n} colors have no clear amount yet, so they\'ll go under Needs attention for you to fill in later.'
        chk(w.startswith('Tick the box above to create your project.') and 'Go to the checkbox' in w and (one if n == 1 else many) in w and '"' not in w and '\u201c' not in w, f'P1 hint N={n} exact plural, no quoted checkbox text', w)
        chk(p.inner_text('label.pat-all').strip() == "I've checked these colors against my pattern" and p.inner_text('#patImport') == 'Create project' and 'These colors aren\'t saved until you create the project.' in p.inner_text('#ffPatternDialog'), f'P2 N={n} checkbox, button and not-saved strings')
        if n == 3 and BB: p.locator('#patWhy').scroll_into_view_if_needed(); p.screenshot(path=os.path.join(BB, 'disabled-button-hint-pixel.png'))
        p.check('#patAll'); p.fill('#patName', f'Pix{n}'); p.click('#patImport'); p.wait_for_timeout(500); sb = p.inner_text('#patSavedBox')
        want = (f'Saved! "Pix{n}" is in My Projects with 2 colors.' if n == 1 else f'Saved! "Pix{n}" is in My Projects with 4 colors.')
        need = '1 color needs an amount, so it\'s under Needs attention.' if n == 1 else '3 colors need an amount, so they\'re under Needs attention.'
        chk(want in sb and need in sb and "You're looking at the project now." in sb and 'See all my projects' in sb and 'Dismiss' in sb, f'P3 saved box N={n} exact plural', sb)
        if n == 3 and BB: p.locator('#patSavedBox').scroll_into_view_if_needed(); p.screenshot(path=os.path.join(BB, 'saved-box-pixel.png'))
    p = page(); paste(p, 'DMC 310 Black 2 skeins'); p.check('#patAll'); p.fill('#patName', 'Pix0'); p.click('#patImport'); p.wait_for_timeout(500); sb = p.inner_text('#patSavedBox')
    chk('with 1 color.' in sb and 'Needs attention' not in sb, 'P3b saved box 1 color, M=0 omits the Needs attention line', sb)
    p = page(); paste(p, 'DMC 310 Black 2 skeins'); w = p.inner_text('#patWhy'); chk('Needs attention' not in w and 'have no clear' not in w, 'P1b hint N=0 omits the amount sentence', w)
    p = page(); info, codes = load(p, 'scanned-image-only.pdf'); u = p.inner_text('#patUnreadable')
    chk(u == "We couldn't find any colors in scanned-image-only.pdf, so nothing was added. This PDF has no text we can read, so it's probably scanned pages. Paste the pattern's color key in the box below instead.", 'P4 scanned: exact sentence order, each once', u)
    pos = p.evaluate("(()=>{const m=document.getElementById('patUnreadable'),d=document.querySelector('details.pat-manual');return m.getBoundingClientRect().bottom<=d.getBoundingClientRect().top})()")
    chk(pos, 'P4b paste box sits BELOW the message (so "below" is accurate)')
    chk('AI scan' not in p.inner_text('#ffPatternDialog') and 'Type the legend' not in p.inner_text('#ffPatternDialog') and 'No reliable colors' not in p.inner_text('#ffPatternDialog'), 'P4c removed lines are gone')
    p.click('#ffPatternDialog .pat-header button'); info, codes = load(p, 'dmc-color-chart.pdf', 4000); u = p.inner_text('#patUnreadable')
    chk(u.startswith("We couldn't find any colors in dmc-color-chart.pdf, so nothing was added. We skipped page") and "like a full DMC color chart, not this pattern's color key." in u and u.endswith("Paste the pattern's color key in the box below instead.") and 'no text' not in u, 'P5 chart: skipped-pages sentence, no scanned sentence', u)
    if BB: p.screenshot(path=os.path.join(BB, 'unreadable-message-pixel.png'))
    p.click('#ffPatternDialog .pat-header button'); p.click('.pat-launch')
    chk(not p.evaluate("document.getElementById('patHelp').open") and p.inner_text('#patHelp summary') == 'How pattern import works', 'P6 help closed by default with the right summary')
    p.click('#patHelp summary'); ht = p.inner_text('#patHelp')
    chk(len(p.locator('#patHelp li').all()) == 6 and "Your file isn't uploaded or kept." in ht and 'use Import a pattern (PDF) there' in ht, 'P6b help has the 6 bullets', ht)
    if BB: p.locator('#patHelp').scroll_into_view_if_needed(); p.screenshot(path=os.path.join(BB, 'help-expanded-pixel.png'))
    chk('\u2014' not in p.inner_text('#ffPatternDialog'), 'P7 no em dashes in the dialog')
    errs = g.errs + h.errs + k.errs + s.errs + z.errs + t.errs
    ok('I13 no page errors', not errs, errs)
print(f'{sum(R)} passed, {len(R)-sum(R)} failed'); sys.exit(0 if all(R) else 1)
